import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../../../Core/Resources/app_icons.dart';import '../../../../../../Core/Services/service_locator.dart';import '../../../../../../Core/Utils/Widget/custom_scaffold_messenger.dart';import '../../../../../../Core/Utils/Widget/default_app_bar.dart';import '../../../../../../Core/Utils/Widget/loading_animation.dart';import '../Cubit/Cart/cart_state.dart';import '../../../../../../Core/Utils/Extensions/localizations_extension.dart';import '../Cubit/Cart/cart_cubit.dart';import '../widgets/body_page_cart_items.dart';import '../widgets/no_item.dart';import '../widgets/persistent_footer_buttons_cart.dart';class CartScreen extends StatelessWidget {  const CartScreen({super.key});  @override  Widget build(BuildContext context) {    final local = context.local;    return BlocProvider(      create: (context) => sl<CartCubit>()..initItems(),      child: BlocConsumer<CartCubit, CartStates>(      listener: (context, state) {        if (state.success == false) {          showCustomSnackBar(context, state.error.toString(), SnackBarType.error);        }      },        builder: (context, state) {          return Scaffold(            appBar: DefaultAppBar(local: local.cart,action:  [            InkWell(              onTap: ()=>context.read<CartCubit>().clearItems(),            child: AppIcons.trash,            ),              30.horizontalSpace,            ],),            body: state.loading == true                ? CustomLoadingAnimation()                : state.loading == null || state.cartItems?.cartItems.isEmpty == true                    ? NoItemsCart(local: local)                    :  BodyPageCartItems(                            cartItems: state.cartItems?.cartItems ?? [],                            local: local,                          ),            persistentFooterButtons: [              PersistentFooterButtonsCart(local: local,state: state,)            ],          );        },      ),    );  }}